import random
import math

def run_trial(seed: int) -> dict:
    n = 40
    max_instances = 30
    instances_tested = min(max_instances, 2 * n)

    def gaussian_elimination(A):
        m, n = len(A), len(A[0])
        for i in range(m):
            max_row = i
            for j in range(i+1, m):
                if abs(A[j][i]) > abs(A[max_row][i]):
                    max_row = j
            A[i], A[max_row] = A[max_row], A[i]
            factor = A[i][i]
            for j in range(n):
                A[i][j] /= factor
            for j in range(m):
                if j != i:
                    factor = A[j][i]
                    for k in range(n):
                        A[j][k] -= factor * A[i][k]
        return A

    def matrix_multiply(A, B):
        m, n, p = len(A), len(B), len(B[0])
        C = [[0] * p for _ in range(m)]
        for i in range(m):
            for j in range(p):
                for k in range(n):
                    C[i][j] += A[i][k] * B[k][j]
        return C

    def random_read_twice_bp(n, instances_tested):
        BPs = []
        for _ in range(instances_tested):
            bp = [[random.choice([-1, 1]) for _ in range(2)] for _ in range(n)]
            BPs.append(bp)
        return BPs

    def path_distribution(bp):
        m = len(bp)
        dp = [0] * (1 << m)
        dp[0] = 1
        for i in range(m):
            new_dp = [0] * (1 << m)
            for j in range(1 << m):
                if dp[j] > 0:
                    new_dp[j ^ bp[i][0]] += dp[j]
                    new_dp[j ^ bp[i][1]] += dp[j]
            dp = new_dp
        return dp

    def moments(dp, order):
        moments = [0] * (order + 1)
        for i in range(1 << len(dp)):
            weight = dp[i]
            moment = sum((i & (1 << j)) != 0 for j in range(len(dp))) ** 2
            for k in range(order):
                moments[k] += weight * moment ** (k // 2)
        return moments

    def free_cumulants(moments):
        cumulants = [moments[0]]
        for i in range(1, len(moments)):
            cumulant = moments[i]
            for j in range(i):
                cumulant -= sum(cumulants[j] * comb(i, j) * (i - j) ** (i - 2 * j) for j in range(j + 1))
            cumulants.append(cumulant)
        return cumulants

    def IP_2_path_distribution(n):
        A = [[random.choice([-1, 1]) for _ in range(n)] for _ in range(n)]
        dp = [0] * (1 << n)
        dp[0] = 1
        for i in range(n):
            new_dp = [0] * (1 << n)
            for j in range(1 << n):
                if dp[j] > 0:
                    new_dp[j ^ A[i][j & (n - 1)]] += dp[j]
            dp = new_dp
        return dp

    def IP_2_moments(dp, order):
        moments = [0] * (order + 1)
        for i in range(1 << len(dp)):
            weight = dp[i]
            moment = sum((i & (1 << j)) != 0 for j in range(len(dp))) ** 2
            for k in range(order):
                moments[k] += weight * moment ** (k // 2)
        return moments

    def IP_2_free_cumulants(moments):
        cumulants = [moments[0]]
        for i in range(1, len(moments)):
            cumulant = moments[i]
            for j in range(i):
                cumulant -= sum(cumulants[j] * comb(i, j) * (i - j) ** (i - 2 * j) for j in range(j + 1))
            cumulants.append(cumulant)
        return cumulants

