import random
import math

def is_prime(n):
    if n <= 1:
        return False
    if n <= 3:
        return True
    if n % 2 == 0 or n % 3 == 0:
        return False
    i = 5
    while i * i <= n:
        if n % i == 0 or n % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_primes(n):
    primes = []
    num = 2
    while len(primes) < n:
        if is_prime(num):
            primes.append(num)
        num += 1
    return primes

def gaussian_elimination(A, b):
    n = len(b)
    for i in range(n):
        max_row = max(range(i, n), key=lambda r: abs(A[r][i]))
        A[i], A[max_row] = A[max_row], A[i]
        b[i], b[max_row] = b[max_row], b[i]
        for j in range(i + 1, n):
            factor = A[j][i] / A[i][i]
            for k in range(i, n):
                A[j][k] -= factor * A[i][k]
            b[j] -= factor * b[i]
    x = [0] * n
    for i in range(n - 1, -1, -1):
        x[i] = (b[i] - sum(A[i][j] * x[j] for j in range(i + 1, n))) / A[i][i]
    return x

def matrix_multiply(A, B):
    m, k = len(A), len(B[0])
    result = [[0] * k for _ in range(m)]
    for i in range(m):
        for j in range(k):
            for l in range(len(B)):
                result[i][j] += A[i][l] * B[l][j]
    return result

def fourier_coefficients(M, n):
    N = 2 ** n
    F = [[0] * N for _ in range(N)]
    for k in range(N):
        for l in range(N):
            sum_val = 0
            for i in range(n):
                sum_val += M[i][l // (2 ** i) % 2] * math.cos(2 * math.pi * k * l / N)
            F[k][l] = sum_val / N
    return F

def run_trial(seed: int) -> dict:
    random.seed(seed)
    n = random.choice([5, 10, 15, 20, 30, 40])
    M = [[random.randint(0, 1) for _ in range(2 ** n)] for _ in range(n)]
    F = fourier_coefficients(M, n)
    min_abs_F = min(abs(F[k][l]) for k in range(len(F)) for l in range(len(F[0])))
    max_abs_F = max(abs(F[k][l]) for k in range(len(F)) for l in range(len(F[0])))
    tau_M = min_abs_F * max_abs_F
    c = 1 / (2 * math.pi)
    conjecture_holds = tau_M >= c * n
    counterexample = "" if conjecture_holds else f"n={n}, tau(M)={tau_M}, expected>=c*n"
    return {
        "metric_name": "tau(M)",
        "metric_value": tau_M,
        "instances_tested": 1,
        "conjecture_holds": conjecture_holds,
        "counterexample": counterexample
    }

