def run_trial(seed: int) -> dict:
    random.seed(seed)

    def gaussian_elimination(A):
        n = len(A)
        for i in range(n):
            max_row = i + max(range(i, n), key=lambda j: abs(A[j][i]))
            A[i], A[max_row] = A[max_row], A[i]
            factor = 1 / A[i][i]
            for j in range(i, n):
                A[i][j] *= factor
            for k in range(n):
                if k != i:
                    factor = A[k][i]
                    for j in range(i, n):
                        A[k][j] -= factor * A[i][j]
        return [row[i] for row in A]

    def matrix_multiplication(A, B):
        m, n, p = len(A), len(B[0]), len(B)
        C = [[0] * n for _ in range(m)]
        for i in range(m):
            for j in range(n):
                for k in range(p):
                    C[i][j] += A[i][k] * B[k][j]
        return C

    def laplacian_eigenvalues(G, d):
        n = len(G)
        L = [[0] * n for _ in range(n)]
        for i in range(n):
            L[i][i] = d - sum(G[i])
            for j in range(i + 1, n):
                if G[i][j]:
                    L[i][j] = L[j][i] = -G[i][j]
        eigenvalues = gaussian_elimination(L)
        return sorted(eigenvalues)

    def tseitin_resolution_length(G, d):
        n = len(G)
        lambda_2 = laplacian_eigenvalues(G, d)[1]
        if lambda_2 < 1e-6:
            return 0
        return 2 ** (math.log(lambda_2) / math.log(2))

    def generate_d_regular_graph(n, d):
        G = [[0] * n for _ in range(n)]
        degree = [0] * n
        edges_added = set()
        while any(d != sum(G[i]) for i in range(n)):
            u = random.randint(0, n - 1)
            v = random.randint(0, n - 1)
            if u == v or G[u][v] or (u, v) in edges_added:
                continue
            G[u][v] = G[v][u] = 1
            degree[u] += 1
            degree[v] += 1
            edges_added.add((u, v))
        return G

    n_values = [5, 10, 15, 20, 30, 40]
    total_length = 0
    instances_tested = 0
    conjecture_holds = True
    counterexample = ""

    for n in n_values:
