    A, B, E = G
    n = len(A)
    M = [[0] * (n + n) for _ in range(n + n)]

    for u, v in E:
        M[u][v], M[v][u] = 1, 1

    def gaussian_elimination(M):
        m, n = len(M), len(M[0])
        rank = 0
        for j in range(n):
