        # Generate a random CNF instance for parity
        cnf = []
        for _ in range(n):
            clause = [random.randint(1, n) * (-1 if random.choice([True, False]) else 1)]
            cnf.append(clause)

        # Compute the communication matrix
        A = [[0] * (2**n) for _ in range(2**n)]
        for i in range(2**n):
            for j in range(2**n):
                if all((i & (1 << abs(l)-1)) == (j & (1 << abs(l)-1)) or l < 0 for l in cnf[i]):
                    A[i][j] = 1

        # Approximate the real dimension of the solution set
        dim = rank(A)

        total_metric_value += dim
        instances_tested += len(n_values)

    metric_value = total_metric_value / instances_tested

    conjecture_holds = math.sqrt(n) <= metric_value for n in n_values]
    if not all(conjecture_holds):
