        monomials = set()
        variables = {'x': 0, 'y': 0}
        for op in bp:
            if op == 'x':
                variables['x'] += 1
            elif op == 'y':
                variables['y'] += 1
            monomials.add(tuple(variables.copy()))
        return monomials

    def hilbert_function(monomials):
        max_degree = 0
        for monomial in monomials:
            degree = sum(monomial)
            if degree > max_degree:
                max_degree = degree
        return max_degree

