def run_trial(seed: int) -> dict:
    random.seed(seed)

    def gaussian_elimination(A, b):
        n = len(A)
        Augmented = [[A[i][j] for j in range(n)] + [b[i]] for i in range(n)]

        for i in range(n):
            max_row = i
            for k in range(i+1, n):
                if abs(Augmented[k][i]) > abs(Augmented[max_row][i]):
                    max_row = k

            Augmented[i], Augmented[max_row] = Augmented[max_row], Augmented[i]

            factor = Fraction(1, Augmented[i][i])
            for j in range(i, n+1):
                Augmented[i][j] *= factor

            for k in range(n):
                if k != i:
                    factor = Augmented[k][i]
                    for j in range(i, n+1):
                        Augmented[k][j] -= factor * Augmented[i][j]

        return [row[-1] for row in Augmented]

    def compute_genus(M):
        n = len(M)
        A = [[0]*n for _ in range(n)]
        b = [0]*n

        for i in range(n):
            for j in range(i+1, n):
                if M[i][j] == 1:
                    A[i][j] = -1
                    A[j][i] = -1
                    b[i] += 1
                    b[j] += 1

        try:
            x = gaussian_elimination(A, b)
        except ZeroDivisionError:
            return None

        genus = sum(x[i]**2 for i in range(n)) / 4
        return genus

    def generate_disjointness_matrix(n):
        M = [[0]*n for _ in range(n)]
        for i in range(n):
            for j in range(i+1, n):
                M[i][j] = random.randint(0, 1)
                M[j][i] = M[i][j]
        return M

    def communication_complexity(M):
        n = len(M)
        CC = 2 * sum(sum(row) for row in M) / (n * (n - 1))
        return CC

    instances_tested = 0
    total_metric_value = 0
    conjecture_holds = True
    counterexample = ""

