import random
import math
from fractions import Fraction

def gaussian_elimination(A, b):
    n = len(b)
    for i in range(n):
        max_row = max(range(i, n), key=lambda r: abs(A[r][i]))
        A[i], A[max_row] = A[max_row], A[i]
        b[i], b[max_row] = b[max_row], b[i]
        lead_coeff = A[i][i]
        for j in range(n):
            A[i][j] /= lead_coeff
        b[i] /= lead_coeff
        for k in range(n):
            if k != i:
                factor = A[k][i]
                for j in range(n):
                    A[k][j] -= factor * A[i][j]
                b[k] -= factor * b[i]
    return A, b

def matrix_multiply(A, B):
    n = len(A)
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            for k in range(n):
                C[i][j] += A[i][k] * B[k][j]
    return C

def determinant(A):
    if len(A) == 1:
        return A[0][0]
    det = 0
    sign = 1
    for j in range(len(A)):
        submatrix = [row[:j] + row[j+1:] for row in A[1:]]
        det += sign * A[0][j] * determinant(submatrix)
        sign *= -1
    return det

def sturm_sequence(coefficients):
    n = len(coefficients)
    if n < 2:
        raise ValueError("Sturm sequence requires at least two coefficients")

    seq = [coefficients[:]]
    while True:
        next_coeff = [-seq[-2][i+1] * (len(seq[-1]) - i - 1) / seq[-1][0] for i in range(len(seq[-2]) - 1)]
        if all(coeff == 0 for coeff in next_coeff):
            break
        seq.append(next_coeff)

    return seq

def count_real_roots(sturm_seq):
    n = len(sturm_seq)
    sign_changes = [sum(1 for i in range(n-1) if sturm_seq[i][j] * sturm_seq[i+1][j] < 0) for j in range(len(sturm_seq[0]))]
    return sum(sign_changes)

def run_trial(seed: int) -> dict:
    random.seed(seed)

    n = random.randint(5, 40)
    edge_weights = [[random.uniform(0.1, 1.0) for _ in range(n)] for _ in range(n)]
    variables = [random.choice([-1, 1]) for _ in range(n)]

    polynomial_coeffs = []
    for i in range(n):
        for j in range(i+1, n):
            coeff = edge_weights[i][j]
            if coeff > 0:
                polynomial_coeffs.append(coeff * (variables[i] + variables[j]))

    sturm_seq = sturm_sequence(polynomial_coeffs)
    real_roots_count = count_real_roots(sturm_seq)

    return {
        "metric_name": "real_root_count",
        "metric_value": real_roots_count,
        "instances_tested": 1,
        "conjecture_holds": False,
        "counterexample": "mapping_undefined"
    }

if __name__ == "__main__":
    import sys
    seeds = [int(s) for s in sys.argv[1:]] or [2**i + 3**i for i in range(5, 8)]

    results = []
    for seed in seeds:
